begin;



-- ---------------------------------------------------------------------------
-- A week of events
-- ---------------------------------------------------------------------------


commit;

-- ---------------------------------------------------------------------------
-- Chat. Channel ids are generated by the cascade, so look them up by team.
-- ---------------------------------------------------------------------------
begin;

with u8 as (
  select id, academy_id from public.channels
   where team_id = '00000000-0000-0000-0000-0000000d0008' and type = 'team'
)
select v.id, u8.academy_id, u8.id, v.sender, v.body, v.anno, v.pinned, v.pinned_by, v.created
from u8, (values
  ('00000000-0000-0000-0000-00000000c001'::uuid,'00000000-0000-0000-0000-0000000000a1'::uuid,
   'Kit is navy this week. Be there 8:30 sharp — Ravens have beaten us twice, let''s start properly.',
   true, now() - interval '2 days', '00000000-0000-0000-0000-0000000000a1'::uuid, now() - interval '2 days'),
  ('00000000-0000-0000-0000-00000000c002'::uuid,'00000000-0000-0000-0000-0000000000b1'::uuid,
   'Is that ELS Hall Park or Christie? I''ve got 14 Kent Rd, North Ryde in my calendar from last time.',
   false, null, null, now() - interval '2 days' + interval '8 minutes'),
  ('00000000-0000-0000-0000-00000000c003'::uuid,'00000000-0000-0000-0000-0000000000a1'::uuid,
   'ELS Hall this week. Pinning the fixture so it''s not buried.',
   false, null, null, now() - interval '2 days' + interval '10 minutes'),
  ('00000000-0000-0000-0000-00000000c004'::uuid,'00000000-0000-0000-0000-0000000000b2'::uuid,
   'Arjun''s got a birthday party but he''ll be there for the morning games 👍',
   false, null, null, now() - interval '1 day'),
  ('00000000-0000-0000-0000-00000000c005'::uuid,'00000000-0000-0000-0000-0000000000b3'::uuid,
   'Can someone bring the spare bibs? Ours are in the wash.',
   false, null, null, now() - interval '3 hours')
) as v(id, sender, body, anno, pinned, pinned_by, created);

-- Reply threading
update public.messages
   set reply_to_id = '00000000-0000-0000-0000-00000000c002'
 where id = '00000000-0000-0000-0000-00000000c003';

-- Reactions on the announcement — including from a parent, which is the one
-- thing that must still work when a channel is set to hosts_only.

-- An availability poll for the gala day, answered per child.
with u8 as (
  select id, academy_id from public.channels
   where team_id = '00000000-0000-0000-0000-0000000d0008' and type = 'team'
)
select '00000000-0000-0000-0000-00000000d001', u8.academy_id, u8.id, 'availability',
       'Gala Day — Sunday 20 September, Valentine Park. Who''s available?',
       '[]'::jsonb, now() + interval '3 days', '00000000-0000-0000-0000-0000000000a1'
from u8;


-- Ravens FC chatter — the rows academy A must never be able to read.
with rv as (
  select id, academy_id from public.channels
   where team_id = '00000000-0000-0000-0000-0000000d0099' and type = 'team'
)
select '00000000-0000-0000-0000-00000000c901', rv.academy_id, rv.id,
       '00000000-0000-0000-0000-0000000000c1',
       'RAVENS INTERNAL: our keeper is injured, play it wide on their left.',
       now() - interval '1 day'
from rv;

commit;
